// Generated by GRAB. Exact values never pass through Number.
export type GrabInteger = string & {readonly __grabInteger: unique symbol};
export type GrabDecimal = string & {readonly __grabDecimal: unique symbol};
export const grabInteger = (s: string): GrabInteger => {if(!/^(0|-[1-9][0-9]*|[1-9][0-9]*)$/.test(s)||s.length>10002)throw new Error("Invalid integer");return s as GrabInteger;};
export const grabDecimal = (s: string): GrabDecimal => {if(!/^-?(0|[1-9][0-9]*)\.[0-9]+$/.test(s)||s.length>10002)throw new Error("Invalid decimal");return s as GrabDecimal;};
export const integerToBigInt = (s: GrabInteger): bigint => BigInt(grabInteger(s));
